type Store<T> = {
  getState: () => T;
  /** Replace the state with updater(state); notify listeners only when it actually changed (Object.is). */
  setState: (updater: (prev: T) => T) => void;
  /** Add a listener; returns a function that removes it. */
  subscribe: (listener: () => void) => () => void;
};

export function createStore<T>(initial: T): Store<T> {
  throw new Error('Not implemented');
}

// Part two (React, written and reviewed, not run here): useStore(store, selector) built on
